/* Références 2026 : taux préremplis, paramètres propres à vérifier. */
const btpSources={urssaf:'https://www.urssaf.fr/accueil/outils-documentation/taux-baremes/taux-cotisations-secteur-prive.html',vieillesse:'https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000048852488',retraite:'https://www.agirc-arrco.fr/entreprises/gerer-une-entreprise/calculer-et-declarer/le-calcul-des-cotisations-de-retraite-complementaire/',btp:'https://www.fntp.fr/baremes-et-taux-2026/'};
function btpReferenceRows(profile){const row=(label,baseMode,employeeRate,employerRate)=>({label,baseMode,base:'0',employeeRate,employerRate});const etam=profile==='ETAM';return[
row('Maladie — taux plein, hors réduction','gross','0','13'),row('Vieillesse plafonnée','t1','6.90','8.55'),row('Vieillesse déplafonnée','gross','0.40','2.11'),row('Allocations familiales — taux plein','gross','0','5.25'),row('Solidarité autonomie','gross','0','0.30'),row('Dialogue social','gross','0','0.016'),row('Assurance chômage — hors bonus/malus','cap4','0','4'),row('AGS — régime général','cap4','0','0.25'),row('Retraite Agirc-Arrco T1'+(etam?' — répartition ETAM BTP':''),'t1',etam?'3.40':'3.15',etam?'4.47':'4.72'),row('Retraite Agirc-Arrco T2'+(etam?' — répartition ETAM BTP':''),'t2',etam?'8.89':'8.64',etam?'12.70':'12.95'),row('CEG T1','t1','0.86','1.29'),row('CEG T2','t2','1.08','1.62'),row('CSG déductible','csg','6.80','0'),row('CSG non déductible','csg','2.40','0'),row('CRDS','csg','0.50','0'),...(profile==='Cadre'?[row('APEC','cap4','0.024','0.036')]:[])];}
function btpCotControls(v,p){return `<div class="wide employee-subblock"><h3>Préremplir les taux BTP · 2026</h3><div class="fields">${selectField('btpProfile','Profil de référence',v.btpProfile||(['Ouvrier','ETAM','Cadre'].includes(p.category)?p.category:'Ouvrier'),['Ouvrier','ETAM','Cadre'])}${field('ceiling','Plafond mensuel applicable au salarié (€)',v.ceiling||4005,'number','min="0.01" step=".01" required')}${field('csgExtra','Complément d’assiette CSG (€), zéro si justifié',v.csgExtra??'','number','min="0" step=".01"')}${selectField('cotReviewed','Paramètres contrôlés pour ce salarié et ce mois',v.cotReviewed||'À vérifier',['À vérifier','Oui'])}<input type="hidden" name="cotTemplateYear" value="${esc(v.cotTemplateYear||'')}"><div class="wide"><button type="button" class="btn secondary" onclick="loadBtpRates()">Préremplir les taux BTP 2026</button><p class="muted">Ajoute les lignes absentes et conserve les lignes déjà saisies. Vérifiez notamment la répartition de retraite applicable à votre adhésion. Les taux spécifiques ne sont jamais devinés.</p></div><p class="wide muted">Assiettes : gross = brut ; t1 = min(brut, plafond) ; t2 = entre 1 et 8 plafonds ; cap4/cap8 = brut limité à 4/8 plafonds ; csg = 98,25 % du brut dans la limite de 4 plafonds + excédent + complément fourni. Plafond à adapter (temps partiel, entrée/sortie, absence). Pas de régularisation annuelle automatique, DFS, exonération d’heures supplémentaires ni RGDU : calcul de test avant allègements.</p><p class="wide notice">À compléter selon vos notifications : AT/MP, mutuelle, prévoyance, FNAL (et majoration congés BTP si applicable), versement mobilité, formation / apprentissage, CET selon le cumul annuel et cotisations caisse CIBTP / intempéries / OPPBTP. Mode CIBTP : aucune retenue automatique sur salaire ni indemnité de congés ajoutée au paiement employeur. Les cotisations dues à la caisse restent à renseigner.</p><p class="wide">Sources : <a href="${btpSources.urssaf}" target="_blank" rel="noopener">Urssaf</a> · <a href="${btpSources.vieillesse}" target="_blank" rel="noopener">Vieillesse 2026</a> · <a href="${btpSources.retraite}" target="_blank" rel="noopener">Agirc-Arrco</a> · <a href="${btpSources.btp}" target="_blank" rel="noopener">Références BTP / ETAM</a></p><div class="wide notice" id="cotLive" aria-live="polite">Les cotisations s’actualisent à partir du brut.</div></div></div>`;}
function loadBtpRates(){if(!period().startsWith('2026')){toast('Ce modèle concerne uniquement les périodes de 2026.');return;}const f=$('#form');const names=new Set([...f.querySelectorAll('[name=cotLabel]')].map(n=>n.value));const profile=f.elements.btpProfile.value;for(const row of btpReferenceRows(profile))if(!names.has(row.label)&&!(row.label.startsWith('Retraite Agirc-Arrco')&&[...names].some(n=>n.startsWith(row.label.split(' — ')[0]))))$('#cotRows').insertAdjacentHTML('beforeend',rowMarkup(row));f.elements.cotTemplateYear.value='2026';f.elements.cotReviewed.value='À vérifier';refreshCalculations();toast('Taux de référence ajoutés. Complétez les paramètres propres à l’entreprise.');}
